insert into public.announcements (slug, title, category, summary, body, pinned, published_at, team_id, athlete_id) values ('austin-dam-leads-mat-broncos-in-fast-paced-win', 'Austin Dam Leads MAT Broncos in Fast-Paced Win', 'team-news', 'Austin Dam and Kyan Cheng combined for a strong offensive night as MAT controlled tempo.', 'Austin Dam set the tone early with aggressive drives and kick-outs, while Kyan Cheng knocked down big perimeter shots. Daniel Guo added steady scoring in transition to keep the Broncos in front.', true, now(), 'MAT-BBB-V', 'p1') on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body;
insert into public.announcements (slug, title, category, summary, body, pinned, published_at, team_id, athlete_id) values ('frontcourt-energy-from-corison-kang-and-ethan-flowers', 'Frontcourt Energy from Corison Kang and Ethan Flowers', 'team-news', 'Corison Kang and Ethan Flowers controlled the glass and gave MAT second-chance points.', 'Corison Kang battled for rebounds throughout all four quarters while Ethan Flowers anchored the paint. Caleb Huang and Zacharia J. Chow provided defensive help on rotations to close possessions.', false, now(), 'MAT-BBB-V', 'p5') on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body;
insert into public.announcements (slug, title, category, summary, body, pinned, published_at, team_id, athlete_id) values ('backcourt-depth-gives-mat-broncos-more-options', 'Backcourt Depth Gives MAT Broncos More Options', 'team-news', 'Ryan J. Lin, Oliver Ho, Justin Lin, and Salem Chancler gave MAT steady production off the bench.', 'Ryan J. Lin kept ball movement sharp, Oliver Ho spaced the floor, and Justin Lin pressured the point of attack. Salem Chancler brought extra energy in transition, helping MAT sustain momentum.', false, now(), 'MAT-BBB-V', 'p7') on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body;
